#!/usr/bin/env python3

"""
Correct Company "Portfolio Size" from associated Locations' "SF Occupied".

Portfolio Size on a Company must equal the sum of the SF Occupied values of
all Locations linked to that Company. Many records drifted (stale or never
set) — e.g. Tarsus Pharmaceuticals had 5,594 stored while its 3 locations
summed to 86,736.

Authentication uses ATTIO_API_KEY_2 (environment or repo .env).

Usage:
  python examples/portfolio/update_portfolio_size.py --dry-run   # preview
  python examples/portfolio/update_portfolio_size.py             # apply

Safety:
- Dry-run mode prints and audits intended changes without writing.
- Companies whose Locations ALL lack an SF Occupied value are skipped by
  default (no evidence to write; a stored value is never clobbered with 0).
  Use --write-zero-when-unknown to override.
- Every decision is appended to a JSONL audit log (paper trail).
- Exits non-zero if any update fails, so schedulers can retry. Reruns are
  idempotent: already-correct companies are skipped.
"""

import argparse
import os
import sys

# Ensure we can import the local package when running from repo root
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", ".."))

import py_attio  # noqa: E402
from py_attio.portfolio import update_portfolio_sizes  # noqa: E402
from py_attio.utils import load_env_file  # noqa: E402

# Load .env from repo root (already-exported env vars win)
load_env_file(os.path.join(os.path.dirname(__file__), "..", "..", ".env"))


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Correct Company Portfolio Size from Locations' SF Occupied"
    )
    parser.add_argument(
        "--api-key",
        default=os.getenv("ATTIO_API_KEY_2", ""),
        help="Attio API key (or set ATTIO_API_KEY_2)",
    )
    parser.add_argument(
        "--company-object", default="companies", help="Company object slug"
    )
    parser.add_argument(
        "--location-object", default="locations", help="Location object slug"
    )
    parser.add_argument(
        "--page-size", type=int, default=500, help="Location pagination size"
    )
    parser.add_argument(
        "--batch-size",
        type=int,
        default=100,
        help="Companies fetched per record_id $in query",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Do not perform updates, only print intended actions",
    )
    parser.add_argument(
        "--write-zero-when-unknown",
        action="store_true",
        help="Also write 0 for companies whose locations all lack SF Occupied",
    )
    parser.add_argument(
        "--per-update-sleep-s",
        type=float,
        default=0.1,
        help="Sleep seconds after each update to be gentle on rate limits",
    )
    parser.add_argument(
        "--audit-file",
        default=".update_portfolio_size_audit.jsonl",
        help=(
            "Append-only JSONL audit log of every decision "
            "(pass empty string to disable)"
        ),
    )
    return parser.parse_args()


def main():
    args = parse_args()
    if not args.api_key:
        print("Error: ATTIO_API_KEY_2 not set and --api-key not provided")
        sys.exit(1)

    client = py_attio.Client(args.api_key)
    sys.exit(
        update_portfolio_sizes(
            client=client,
            company_object=args.company_object,
            location_object=args.location_object,
            page_size=args.page_size,
            batch_size=args.batch_size,
            dry_run=args.dry_run,
            write_zero_when_unknown=args.write_zero_when_unknown,
            per_update_sleep_s=args.per_update_sleep_s,
            audit_file=args.audit_file or None,
        )
    )


if __name__ == "__main__":
    main()
